package org.simpleweather.app;
import java.time.*;
import java.util.*;
import org.json.*;
public final class TodoTests {
    static int checks;static void check(boolean v,String why){checks++;if(!v)throw new AssertionError(why);}
    static TodoModel.Item item(){TodoModel.Item i=new TodoModel.Item();i.title="Task";i.date=LocalDate.of(2026,11,1);i.until=i.date;i.created=i.updated=0;i.slots.add(new TodoModel.Slot(540,600));return i;}
    static long at(String date,int minute,ZoneId z){return TodoModel.at(LocalDate.parse(date),minute,z);}
    static void invalid(TodoModel.Item i,String why){boolean failed=false;try{TodoModel.validate(i);}catch(Exception e){failed=true;}check(failed,why);}
    static void bad(JSONObject j,String why){boolean failed=false;try{TodoModel.parse(j.toString());}catch(Exception e){failed=true;}check(failed,why);}
    public static void main(String[] args)throws Exception{
        ZoneId z=ZoneId.of("Asia/Shanghai");long now=at("2026-11-01",480,z);TodoModel.Item i=item();
        TodoModel.validate(i);check(TodoModel.next(i,now,z).start==at("2026-11-01",540,z),"Timed start");check(TodoModel.next(i,now,z).end==at("2026-11-01",600,z),"Timed end");
        i.slots.add(new TodoModel.Slot(900,960));i.remindEnd=true;List<TodoModel.Event> events=TodoModel.events(i,now,z,540,0);check(events.size()==4,"Two intervals each have start and end reminder");check(events.stream().filter(e->e.end).count()==2,"Separate end reminders");check(new HashSet<String>(Arrays.asList(events.get(0).key,events.get(1).key,events.get(2).key,events.get(3).key)).size()==4,"Unique slot keys");
        i.advance=15;check(TodoModel.events(i,now,z,540,0).get(0).when==at("2026-11-01",525,z),"Advance reminder");i.updated=at("2026-11-01",530,z);check(TodoModel.events(i,now,z,540,0).get(0).when==at("2026-11-01",540,z),"Editing after advance falls back to upcoming start");
        check(TodoModel.events(i,now,z,540,at("2026-11-02",0,z)).isEmpty(),"Import cutoff excludes past reminders");i.advance=-1;check(TodoModel.events(i,now,z,540,0).isEmpty(),"Off disables end reminders too");
        i=item();i.allDay=true;i.until=i.date.plusDays(2);TodoModel.Occurrence o=TodoModel.next(i,now,z);check(o.start==at("2026-11-01",0,z),"All-day begins midnight");check(o.end==at("2026-11-04",0,z),"Multi-day inclusive last date");i.remindEnd=true;events=TodoModel.events(i,now,z,600,0);check(events.get(0).when==at("2026-11-01",600,z),"All-day configured reminder time");check(events.get(1).when==o.end,"Multi-day end reminder");i.repeat=1;invalid(i,"Multi-day repeat rejected");
        i=item();i.repeat=1;i.parts.add(new TodoModel.Part("Part",true));TodoModel.complete(i,i.date);check(!i.done,"Recurring completion is not permanent");check(i.completedThrough.equals("2026-11-01"),"Occurrence completion stored");check(!i.parts.get(0).done,"Checklist resets for next occurrence");check(TodoModel.next(i,now,z).day.equals(LocalDate.of(2026,11,2)),"Next day after completion");check(!TodoModel.occurs(i,i.date),"Already completed occurrence excluded");
        i=item();i.repeat=2;check(TodoModel.next(i,at("2026-11-02",500,z),z).day.equals(LocalDate.of(2026,11,8)),"Weekly rule");i.repeat=3;check(TodoModel.next(i,now,z).day.equals(LocalDate.of(2026,11,2)),"Weekdays skip Sunday");i.repeat=4;i.weekMask=(1<<1)|(1<<4);check(TodoModel.next(i,now,z).day.equals(LocalDate.of(2026,11,3)),"Selected weekdays");i.weekMask=0;invalid(i,"Empty custom weekday rule rejected");
        i=item();TodoModel.complete(i,i.date);check(i.done&&TodoModel.next(i,now,z)==null,"Once completion");check(TodoModel.events(i,now,z,540,0).isEmpty(),"Complete tasks have no reminders");
        i=item();check(TodoModel.next(i,at("2026-11-03",0,z),z).end<at("2026-11-03",0,z),"Overdue once remains accessible");check(TodoModel.events(i,at("2026-11-05",0,z),z,540,0).isEmpty(),"No old catch-up alerts");
        i=item();i.date=LocalDate.of(2026,3,8);i.until=i.date;i.allDay=true;ZoneId ny=ZoneId.of("America/New_York");o=TodoModel.next(i,now,ny);check(o.end-o.start==23*3600000L,"DST all-day is local calendar day not fixed 24 hours");
        check(TodoModel.at(LocalDate.of(2026,3,8),150,ny)==ZonedDateTime.of(2026,3,8,3,30,0,0,ny).toInstant().toEpochMilli(),"Missing DST time shifts through gap");
        i=item();i.slots.clear();i.slots.add(new TodoModel.Slot(1430,1440));TodoModel.validate(i);check(TodoModel.next(i,now,z).end==at("2026-11-02",0,z),"End at 24:00");check(TodoModel.minute("8:05")==485,"Direct hours and minutes");for(String v:new String[]{"24:00","12:60","-1:00","10","a:b","1:1"}){boolean fail=false;try{TodoModel.minute(v);}catch(Exception e){fail=true;}check(fail,"Reject malformed clock "+v);}
        TodoModel model=new TodoModel();i=item();i.title="Sample";i.note="Lines\nMore";i.category="Work";i.color=0xffb83232;i.pin=true;i.parts.add(new TodoModel.Part("Part",true));model.items.add(i);TodoModel parsed=TodoModel.parse(model.json().toString());check(parsed.items.size()==1&&parsed.items.get(0).id.equals(i.id),"Stable identity round trip");check(parsed.items.get(0).parts.get(0).done&&parsed.items.get(0).color==i.color&&parsed.items.get(0).pin,"Checklist, colors and pin round trip");check(parsed.items.get(0).note.equals(i.note),"Multiline notes round trip");
        JSONObject root=model.json();JSONObject row=root.getJSONArray("items").getJSONObject(0);Object[][] bad={{"title",""},{"allDay","true"},{"priority",1.1},{"priority",9},{"advance",2},{"color",1},{"date","2026-02-30"},{"until","2026-10-31"},{"repeat",6},{"weekMask",256},{"updated",-1},{"completedThrough","2020-01-01"}};for(Object[] b:bad){JSONObject copy=new JSONObject(root.toString());copy.getJSONArray("items").getJSONObject(0).put((String)b[0],b[1]);bad(copy,"Reject field "+b[0]);}
        JSONObject duplicate=new JSONObject(root.toString());duplicate.getJSONArray("items").put(row);bad(duplicate,"Duplicate identities rejected");bad(new JSONObject(root.toString()).put("version",2),"Future format rejected");
        i=item();i.slots.add(new TodoModel.Slot(550,650));invalid(i,"Overlap rejected");i=item();i.slots.add(new TodoModel.Slot(600,650));TodoModel.validate(i);check(i.slots.size()==2,"Adjacent slots allowed");i=item();i.slots.clear();invalid(i,"No timed slots rejected");
        i=item();i.title=new String(new char[161]).replace('\0','x');invalid(i,"Title bounded");i=item();for(int n=0;n<51;n++)i.parts.add(new TodoModel.Part("Part",false));invalid(i,"Checklist bounded");
        Map<String,Map<String,?>> groups=new HashMap<>();groups.put("todos",Collections.singletonMap("data",model.json().toString()));Map<String,Object> p=new HashMap<>();p.put("todo_day_minute",1439);p.put("todo_default_advance",-1);p.put("todo_summary_count",5);p.put("todo_private",true);groups.put("toolbox",p);JSONObject config=ConfigurationData.encode(groups,null);ConfigurationData.Document doc=ConfigurationData.parse(config.toString());check(doc.todos==1&&doc.todoSpecified,"Tasks included in config preview");check(doc.groups.get("toolbox").get("todo_summary_count").equals(5),"Settings round trip");config.remove("todos");check(!ConfigurationData.parse(config.toString()).todoSpecified,"Old config preserves tasks");
        for(int value:new int[]{-1,1440}){JSONObject c=ConfigurationData.encode(groups,null);c.getJSONObject("toolbox").getJSONObject("todo_day_minute").put("value",value);boolean rejected=false;try{ConfigurationData.parse(c.toString());}catch(Exception e){rejected=true;}check(rejected,"Reject invalid reminder minute");}
        System.out.println("Todo tests: "+checks+" checks passed");
    }
}
